import React, { useEffect, useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { Pedometer } from 'expo-sensors';

export default function {{component_name}}() {
  const [steps, setSteps] = useState(0);
  const goal = {{goal_steps}};

  useEffect(() => {
    const start = new Date();
    start.setHours(0, 0, 0, 0);
    Pedometer.getStepCountAsync(start, new Date())
      .then(r => setSteps(r.steps))
      .catch(() => setSteps(0));
    const sub = Pedometer.watchStepCount(r => setSteps(s => s + r.steps));
    return () => sub && sub.remove();
  }, []);

  const pct = Math.min(100, Math.round((steps / goal) * 100));
  return (
    <View style={styles.box}>
      <Text style={styles.num}>{steps}</Text>
      <Text style={styles.sub}>/ {goal} steps ({pct}%)</Text>
    </View>
  );
}
const styles = StyleSheet.create({
  box: { padding: 24, alignItems: 'center' },
  num: { fontSize: 56, fontWeight: '700', color: '{{accent_color}}' },
  sub: { fontSize: 14, color: '#666', marginTop: 4 }
});
